ControlPropertyState.AutoRuleBindingString:
With(
    {
        cli: Table1_1.Selected.'Cliente atribuido',
        dir: Table1_1.Selected.SourceEmailAddress,
        ges: Table1_1.Selected.Name
    },
    With(
        {
            rfc: Patch(
                'CH-Tbl-ClientDataChangeRequests',
                Defaults('CH-Tbl-ClientDataChangeRequests'),
                {
                    Type: 'Type (CH-Tbl-ClientDataChangeRequests)'.Create,
                    ChangeStatus: 'Change Status (CH-Tbl-ClientDataChangeRequests)'.Submitted,
                    TargetTable: "sanic_chtblclientemail",
                    'Related Client': cli,
                    Reason: "Alta de remitente detectada por CashHub en " & ges &
                            ". La direccion " & dir &
                            " envio un pre-registro con la plantilla oficial y el CIF de este cliente."
                }
            )
        },
        Patch(
            'CH-Tbl-ClientDataChangeRequestLines',
            Defaults('CH-Tbl-ClientDataChangeRequestLines'),
            {
                ChangeRequestId: rfc,
                FieldDefinition: LookUp('CH-Tbl-ClientTableLogicalFieldNames',
                    Table = "sanic_chtblclientemail" And LogicalName = "sanic_name"),
                NewValue: dir
            }
        );
        Patch(
            'CH-Tbl-ClientDataChangeRequestLines',
            Defaults('CH-Tbl-ClientDataChangeRequestLines'),
            {
                ChangeRequestId: rfc,
                FieldDefinition: LookUp('CH-Tbl-ClientTableLogicalFieldNames',
                    Table = "sanic_chtblclientemail" And LogicalName = "sanic_Client"),
                NewValue: cli.'CH-Tbl-Clients'
            }
        );
        Notify(
            "Solicitud " & rfc.Name & " creada y enviada a aprobacion. Usted no puede aprobarla: la revisa otra persona de Banca de Empresas.",
            NotificationType.Success
        )
    )
);

UpdateContext(
    {
        varFiltrosQueryCorreo: Concatenate(
            "$filter=",
            If(
                !IsBlank('dp FechaDesde'.SelectedDate),
                "receivedDateTime ge " & Text(
                    'dp FechaDesde'.SelectedDate,
                    "yyyy-mm-dd"
                ) & "T00:00:00Z"
                //,"receivedDateTime ge 2000-01-01T00:00:00Z"
            ),
             If(Or(
                    And(
                        !IsBlank(Trim(SearchInput1_1.Value)),
                        !IsBlank('dp FechaDesde'.SelectedDate)
                    ),And(
                        !IsBlank('dp FechaHasta'.SelectedDate),
                        !IsBlank('dp FechaDesde'.SelectedDate)
                    )
                )," AND "),
            If(
                !IsBlank('dp FechaHasta'.SelectedDate),
                "receivedDateTime le " & Text(
                    'dp FechaHasta'.SelectedDate,
                    "yyyy-mm-dd"
                ) & "T00:00:00Z"
            ),
            If(
                Or(
                    And(
                        !IsBlank(Trim(SearchInput1_1.Value)),
                        !IsBlank('dp FechaHasta'.SelectedDate)
                    )
                ),
                " AND "
            ), 
            If(
                !IsBlank(Trim(SearchInput1_1.Value)),
                //"from/emailAddress/address eq '" & Trim(TextInputCanvas1.Value)&"'"
                "contains(from/emailAddress/address,'" & Trim(SearchInput1_1.Value)&"')"
            )
        )
    }
);

Select(btn_ConstruirURI);
